package com.citacloud.springboot.contacloud.app.views;import com.citacloud.springboot.contacloud.app.security.TenantPrincipal;import org.junit.jupiter.api.*;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.context.SecurityContextHolder;import java.util.*;import static org.assertj.core.api.Assertions.*;
